public class Main {
    public static void main(String[] args) {
        int big = Integer.MAX_VALUE;          // 2147483647
        System.out.println(big + 1);          // wraps to -2147483648
        long safe = (long) big + 1;           // cast BEFORE adding
        System.out.println(safe);             // 2147483648

        System.out.println(7 / 2);            // 3  (integer division)
        System.out.println(7 / 2.0);          // 3.5
        System.out.println(-7 % 3);           // -1 (remainder keeps the sign of the dividend)
        System.out.println(Math.floorMod(-7, 3)); // 2 (the "mathematical" modulo)

        final int MOD = 1_000_000_007;
        long x = 123456789L * 987654321L % MOD;
        System.out.println(x);
    }
}

import java.util.*;

public class Main {
    static void mutate(int[] arr, int x, List<Integer> list, StringBuilder sb) {
        arr[0] = 99;          // changes the caller's array (same object)
        x = 99;               // changes only the local copy of the int
        list.add(7);          // changes the caller's list
        sb.append("!");       // changes the caller's builder
        sb = new StringBuilder("new");   // rebinding the local reference: caller unaffected
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3};
        int x = 5;
        List<Integer> list = new ArrayList<>();
        StringBuilder sb = new StringBuilder("hi");
        mutate(arr, x, list, sb);
        System.out.println(arr[0] + " " + x + " " + list + " " + sb);   // 99 5 [7] hi!

        String a = new String("abc"), b = new String("abc");
        System.out.println((a == b) + " " + a.equals(b));               // false true
        Integer p = 127, q = 127, r = 1000, s = 1000;
        System.out.println((p == q) + " " + (r == s) + " " + r.equals(s)); // true false true

        int[] copy = arr.clone();                                        // shallow copy of the array
        copy[0] = -1;
        System.out.println(arr[0] + " " + copy[0]);                      // 99 -1
        int[][] grid = {{1, 2}, {3, 4}};
        int[][] shallow = grid.clone();                                  // rows are SHARED
        shallow[0][0] = 100;
        System.out.println(grid[0][0]);                                  // 100
    }
}

import java.util.*;

public class Main {
    static boolean isPalindrome(String s) {
        int i = 0, j = s.length() - 1;
        while (i < j) {
            if (s.charAt(i++) != s.charAt(j--)) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(isPalindrome("level"));      // true
        StringBuilder sb = new StringBuilder();
        for (char c = 'a'; c <= 'e'; c++) sb.append(c).append('-');
        sb.setLength(sb.length() - 1);                  // drop the last '-'
        System.out.println(sb);                         // a-b-c-d-e
        System.out.println(sb.reverse());               // e-d-c-b-a

        int[] counts = new int[26];                     // letter frequencies
        for (char c : "banana".toCharArray()) counts[c - 'a']++;
        System.out.println(counts['a' - 'a'] + " " + counts['n' - 'a']); // 3 2
    }
}

