import java.util.*;

public class Main {
    public static void main(String[] args) {
        // frequency counting
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : "mississippi".toCharArray()) freq.merge(c, 1, Integer::sum);
        System.out.println(freq);                          // {p=2, s=4, i=4, m=1} (order may vary)

        // two-sum with a map: value -> index
        int[] nums = {2, 7, 11, 15};
        int target = 9;
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            Integer j = seen.get(target - nums[i]);
            if (j != null) { System.out.println(j + " " + i); break; }
            seen.put(nums[i], i);
        }

        // grouping with computeIfAbsent
        Map<Integer, List<String>> byLen = new TreeMap<>();
        for (String w : new String[]{"to", "be", "or", "not"})
            byLen.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);
        System.out.println(byLen);                          // {2=[to, be, or], 3=[not]}

        TreeSet<Integer> set = new TreeSet<>(List.of(10, 20, 30));
        System.out.println(set.floor(25) + " " + set.ceiling(25)); // 20 30
    }
}

import java.util.*;

public class Main {
    static final class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return r == p.r && c == p.c;
        }
        @Override public int hashCode() { return Objects.hash(r, c); }
    }

    public static void main(String[] args) {
        Set<Point> seen = new HashSet<>();
        seen.add(new Point(1, 2));
        System.out.println(seen.contains(new Point(1, 2)));          // true (equals + hashCode)

        Set<int[]> bad = new HashSet<>();
        bad.add(new int[]{1, 2});
        System.out.println(bad.contains(new int[]{1, 2}));           // false: arrays use identity

        Set<List<Integer>> ok = new HashSet<>();
        ok.add(List.of(1, 2));
        System.out.println(ok.contains(List.of(1, 2)));              // true: List has value equality

        record Cell(int r, int c) {}                                  // records get equals/hashCode for free
        Set<Cell> cells = new HashSet<>(List.of(new Cell(0, 0)));
        System.out.println(cells.contains(new Cell(0, 0)));          // true

        Map<Integer, Integer> lru = new LinkedHashMap<>(16, 0.75f, true) {   // access-ordered: an LRU cache
            protected boolean removeEldestEntry(Map.Entry<Integer, Integer> e) { return size() > 2; }
        };
        lru.put(1, 1); lru.put(2, 2); lru.get(1); lru.put(3, 3);
        System.out.println(lru.keySet());                            // [1, 3]
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(1); stack.push(2);
        System.out.println(stack.pop());                    // 2

        Queue<Integer> q = new ArrayDeque<>();
        q.offer(1); q.offer(2);
        System.out.println(q.poll());                       // 1

        PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> x[0] - y[0]); // min by first field
        pq.offer(new int[]{5, 100});
        pq.offer(new int[]{2, 200});
        System.out.println(pq.poll()[1]);                   // 200

        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Comparator.reverseOrder());
        maxHeap.addAll(List.of(3, 9, 4));
        System.out.println(maxHeap.peek());                 // 9
    }
}

