import sys

def two_sum(a, target):
    seen = {}
    for j, x in enumerate(a):
        if target - x in seen:
            return seen[target - x] + 1, j + 1
        seen.setdefault(x, j)
    return None

def main():
    data = sys.stdin.read().split()
    n, t = int(data[0]), int(data[1])
    a = list(map(int, data[2:2 + n]))
    r = two_sum(a, t)
    print("-1" if r is None else f"{r[0]} {r[1]}")

