	sort.Ints(a)
	fmt.Println(a, len(a), a[1:3]) // [1 2 5 9] 4 [2 5]

	a = append(a, 10) // always reassign the result of append
	fmt.Println(a)

	b := a[:2] // a re-slice SHARES memory with a
	b[0] = 100
	fmt.Println(a[0]) // 100

	c := make([]int, len(a)) // an independent copy
	copy(c, a)
	c[0] = 7
	fmt.Println(a[0], c[0]) // 100 7

	grid := make([][]int, 3)
	for i := range grid {
		grid[i] = make([]int, 4)
