import "fmt"

func main() {
	n := 6
	edges := [][2]int{{0, 1}, {0, 2}, {1, 3}, {2, 3}, {3, 4}, {2, 5}}
	adj := make([][]int, n)
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], e[1])
		adj[e[1]] = append(adj[e[1]], e[0]) // undirected
	}

	dist := make([]int, n)
	for i := range dist {
		dist[i] = -1
	}
	queue := []int{0}
	dist[0] = 0
	for head := 0; head < len(queue); head++ {
		u := queue[head]
		for _, v := range adj[u] {
			if dist[v] == -1 {
				dist[v] = dist[u] + 1
				queue = append(queue, v)
			}
		}
	}
	fmt.Println(dist) // [0 1 1 2 3 2]
}

