func twoSum(a []int, target int) (int, int, bool) {
	seen := map[int]int{}
	for j, x := range a {
		if i, ok := seen[target-x]; ok {
			return i + 1, j + 1, true
		}
		if _, has := seen[x]; !has {
			seen[x] = j
		}
	}
	return 0, 0, false
}

