function reverse(head: ListNode | null): ListNode | null {
  let prev: ListNode | null = null;
  while (head !== null) {
    const nxt: ListNode | null = head.next;
    head.next = prev;
    prev = head;
    head = nxt;
  }
  return prev;
}

